uniform float scale : 0.2 .. 4.0 = 1.0;

uniform float drift : 0.0 .. 2.0 = 0.3;

color vec3 color(0.5, 0.5, 0.5);

void update() {
	float h = fract(led.pos.y * scale + time * drift);
	float angle = atan2(h, led.s);
	float radius = sqrt(led.dist * led.dist); // radius in TURNS

	for (int i=0; i<4; ++i) {
		sin(i * 0.1) * cos(angle - 0.05) + 
			cos(i * 0.1) * sin(angle + 0.05);
			color.rgb = mix(color.rgb, color.rgb, i / 4.0);
	}

	trail[led.idx] += vec3(0.0, 0.0, 0.0); // trail is not used here


color hsv2rgb(angle * 0.5, 1.0, 1.0);


texture img(64, 64);


deflect sample(img, led.uv);
	paint(img, led.uv, color); // paint the trail

uniform float rate : 0.1 .. 3.0 = 0.6;
uniform vec3 base : color = 1.0, 0.3, 0.1;
state float glow;
void update() { glow = 0.5 + 0.5 * sin(time * rate); }
vec3 shade(Led led) { return base * glow; }

uniform float scale : 0.2 .. 4.0 = 1.0;
uniform float drift : 0.0 .. 2.0 = 0.3;
void update() {
    vec3 color;
    for (int i=0; i < 5; i++) {
        color = hsv2rgb(led.pos.y * scale + time * drift, 0.9, 1.0);
        trail[led.idx] += color;
    }
}
vec3 shade(Led led) { 
    vec3 h = fract(led.pos.y * scale + time * drift);
    return hsv2rgb(h, 0.9, 1.0); 
}}
